import type { AttachmentClass, Cell, Tier } from '../config'
import type { WorkStatus, WorkTransition } from '../detect/work-source'
import type { Puzzle } from '../puzzle/puzzle'

// SPEC 10, extended for the slice. Times are epoch milliseconds from $.clock.

export type Versioned<T> = T & { schemaVersion: number }

export type Point = { x: number; y: number }
export type Anchors = { head: Point; neck: Point; hand: Point; orbit: Point }
export type Sprite = { rows: string[] }

export type Species = {
  id: string
  kind: 'fauna' | 'flora'
  tier: Tier
  name: string
  readout: string
  behavior: string
  stages: Sprite[]
  anchors: Anchors
  /** True when the art (or name) came from the procedural library. */
  isProcedural: boolean
}

export type Biome = { name: string; description: string }

export type StarSystem = {
  id: string
  epicKey: string
  name: string
  starClass: string
  lore: string
  biomes: Biome[]
  species: Species[]
  status: 'open' | 'surveyed'
  chartedAt: number
  surveyedAt?: number
}

export type Mission = {
  issueKey: string
  systemId: string
  startedAt: number
  completedAt?: number
  commits: number
  testRuns: number
  testsGreen: boolean
  /** The last lint or type-check verdict during the mission; null before one runs. */
  lint: 'pass' | 'fail' | null
  tacticalClean: boolean
  /**
   * What completing it gave, so `/mission reopen` takes back exactly that:
   * whether it counted as a completed mission, the Reinforced and Stasis
   * Cells it earned, the flora samples it harvested (per species id), and the
   * XP the companion of the time earned (absent when none did). Set on
   * completed missions in the log; absent on the active one.
   */
  reward?: MissionReward
}

export type MissionReward = {
  counted: boolean
  reinforced: number
  stasis: number
  flora: Record<string, number>
  companionXp?: { specimenId: string; xp: number }
}

export type Specimen = {
  id: string
  speciesId: string
  systemId: string
  tier: Tier
  attachment?: { class: AttachmentClass; item: string }
  /** SPEC 9.3: `level` follows from the total `xp`; `stage` rises at evolution levels and never goes back. */
  level: number
  xp: number
  stage: 0 | 1 | 2
  containedAt: number
  nickname?: string
}

export type PendingEncounter = {
  id: string
  systemId: string
  speciesId: string
  tier: Tier
  attachment?: { class: AttachmentClass; item: string }
  quality: number
  attempts: number
  createdAt: number
  /** The mission that rolled it; absent for a survey's or developer mode's. */
  missionKey?: string
  /** SPEC 8: its Analyze Specimen puzzle once prepared; null when none could be made. Its code is the local text the pane shows (puzzle view spec, section 4). */
  puzzle?: Puzzle | null
  /** The puzzle's outcome, kept for every attempt on this creature; `isDisputed` once the player disputed it (SPEC 8.1 rule 4). */
  analysis?: { isSkipped: boolean; isCorrect: boolean; bonus: number; isDisputed?: boolean }
}

/** SPEC 8.2: accuracy per puzzle category. `lastSeen` is epoch milliseconds; `recent` is the last answers, newest last (right is true). */
export type PuzzleStat = { category: string; type: string; attempts: number; correct: number; lastSeen: number; recent: boolean[] }

/** SPEC 8.1 rule 4: a puzzle the player disputed, kept for review (its code is the local text it showed; no mission key, which is work content). */
export type PuzzleDispute = Puzzle & { at: number; wasCorrect: boolean }

export type Inventory = Record<Exclude<Cell, 'standard'>, number> & { flora: Record<string, number> }

export type CatalogEntry = {
  speciesId: string
  tier: Tier
  attachment?: string
  status: 'seen' | 'contained' | 'escaped'
}

export type SaveMeta = {
  createdAt: number
  firstTrackedAt: number | null
  lastEncounterAt: number | null
  completedMissions: number
  activeEpicKey: string | null
  companionId: string | null
  /** SPEC 4.3 soft cap: encounters rolled from missions on `day` (host local date, YYYY-MM-DD). */
  encountersToday: { day: string; count: number }
}

/** `salt` makes client keys unguessable from the values they hash (generated once per install). */
export type Calibration = { clients: Record<string, { offsetMs: number; measuredAt: number }>; salt: string }

/**
 * SPEC 4.2: where one work source's sync left off (one record per source,
 * SPEC 4.4). `lastSync` is null until that source's first sync, which starts
 * from that moment (nothing before it is awarded). `processed` holds
 * `<issueKey>:<transitionId>` for each applied transition. `waiting` holds
 * changes that could not apply yet, tried again at each sync (rule 5).
 */
export type SyncState = { lastSync: number | null; processed: string[]; waiting: WorkTransition[] }

/**
 * SPEC 4.4 rule 3: what the plan documents of one project last read as. A
 * task stays when it disappears from the files, so a file briefly missing
 * reports nothing when it returns. `log` keeps recent changes, newest last,
 * so a sync that failed, or one reaching back by the overlap, reads them
 * again. `epoch`: when the baseline was read, part of every transition id.
 */
export type PlansState = {
  epoch: number
  tasks: Record<string, { status: WorkStatus }>
  doneEpics: string[]
  log: WorkTransition[]
  seq: number
}

/** SPEC 9.2: one `/captains-log` entry. */
export type LogEntry = { at: number; stardate: string; lines: string[] }

/** SPEC 9.1: an officer's last report, kept so the Bridge can show it again. Stays on this machine. */
export type CrewReport = { role: 'engineering' | 'science' | 'tactical'; at: number; lines: string[] }

